import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Which sample the Geiger engine should play for the current zone.
enum PingTone { cold, warm, hot }

/// Sound engine for the Geiger pings and the "found it" chime.
///
/// Samples are tiny mono WAV files generated by `tool/generate_audio.py` and
/// bundled as Flutter assets, so playback works fully offline with no audio
/// focus surprises. Overlapping calls are guarded: at the hot end of the radar
/// a ping can fire every ~130 ms.
class AudioService {
  AudioService({AudioPlayer? pingPlayer, AudioPlayer? successPlayer})
      : _ping = pingPlayer ?? AudioPlayer(playerId: 'radar-ping'),
        _success = successPlayer ?? AudioPlayer(playerId: 'radar-success');

  static const String pingAsset = 'audio/ping.wav';
  static const String warmPingAsset = 'audio/ping_warm.wav';
  static const String hotPingAsset = 'audio/ping_hot.wav';
  static const String successAsset = 'audio/success.wav';

  final AudioPlayer _ping;
  final AudioPlayer _success;

  bool _initialised = false;
  bool _pingBusy = false;
  bool enabled = true;

  bool get isReady => _initialised;

  Future<void> initialize() async {
    try {
      await _ping.setReleaseMode(ReleaseMode.stop);
      await _ping.setSource(AssetSource(pingAsset));
      await _ping.setVolume(0.45);
      await _success.setReleaseMode(ReleaseMode.stop);
      await _success.setSource(AssetSource(successAsset));
      await _success.setVolume(0.9);
      _initialised = true;
    } on Exception catch (error) {
      debugPrint('AudioService init failed: $error');
    }
  }

  static String assetFor(PingTone tone) => switch (tone) {
        PingTone.cold => pingAsset,
        PingTone.warm => warmPingAsset,
        PingTone.hot => hotPingAsset,
      };

  /// Plays one proximity ping. Silently ignored while the previous call is
  /// still in flight (the next tick will come soon enough).
  Future<void> ping({double volume = 0.45, PingTone tone = PingTone.cold}) async {
    if (!enabled || !_initialised || _pingBusy) return;
    _pingBusy = true;
    try {
      await _ping.play(
        AssetSource(assetFor(tone)),
        volume: volume.clamp(0.05, 1.0).toDouble(),
      );
    } on Exception catch (error) {
      debugPrint('ping failed: $error');
    } finally {
      _pingBusy = false;
    }
  }

  Future<void> playSuccess() async {
    if (!enabled || !_initialised) return;
    try {
      await _success.play(AssetSource(successAsset));
    } on Exception catch (error) {
      debugPrint('success sound failed: $error');
    }
  }

  Future<void> stopPing() async {
    try {
      await _ping.stop();
    } on Exception catch (error) {
      debugPrint('stopPing failed: $error');
    }
  }

  Future<void> dispose() async {
    await _ping.dispose();
    await _success.dispose();
    _initialised = false;
  }
}
